//! The overlays' bundled fonts (third_party/fonts/libertinus) as byte arrays
//! in a C++ file of the build's own. Ported from nx2/ui_fonts.py.

use std::fs;
use std::path::Path;

use serde_json::{Value, json};

pub const FILES: [(&str, &str); 3] = [
    ("hookshot_font_body", "LibertinusSans-Regular.ttf"),
    ("hookshot_font_strong", "LibertinusSans-Bold.ttf"),
    ("hookshot_font_heading", "LibertinusSerif-Semibold.ttf"),
];

pub fn source(root: &Path) -> Result<String, String> {
    let fonts = root.join("third_party/fonts/libertinus");
    let mut lines = vec![
        "// generated by nx2/ui_fonts.py from third_party/fonts/libertinus (SIL Open Font License 1.1): do not edit".to_owned(),
    ];
    for (name, file) in FILES {
        let data = fs::read(fonts.join(file))
            .map_err(|e| format!("{}: {e}", fonts.join(file).display()))?;
        lines.push(format!(
            "extern const unsigned {name}_size = {};",
            data.len()
        ));
        lines.push(format!(
            "extern const unsigned char {name}[{}] = {{",
            data.len()
        ));
        for chunk in data.chunks(48) {
            lines.push(format!(
                "{},",
                chunk
                    .iter()
                    .map(|byte| byte.to_string())
                    .collect::<Vec<_>>()
                    .join(",")
            ));
        }
        lines.push("};".to_owned());
    }
    Ok(lines.join("\n") + "\n")
}

/// Write the C++ file when it differs; returns the fonts' bytes for the object key.
pub fn write(out: &Path, root: &Path) -> Result<usize, String> {
    let text = source(root)?;
    let same = fs::read_to_string(out)
        .map(|old| old == text)
        .unwrap_or(false);
    if !same {
        if let Some(parent) = out.parent() {
            fs::create_dir_all(parent).map_err(|e| format!("{}: {e}", parent.display()))?;
        }
        fs::write(out, text).map_err(|e| format!("{}: {e}", out.display()))?;
    }
    Ok(FILES
        .iter()
        .filter_map(|(_, file)| fs::read(root.join("third_party/fonts/libertinus").join(file)).ok())
        .map(|data| data.len())
        .sum())
}

pub fn write_json(out: &str) -> Result<Value, String> {
    let root = crate::kit::root();
    let bytes = write(Path::new(out), &root)?;
    Ok(json!({"out": out, "bytes": bytes}))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn writes_the_bundled_fonts() {
        let out =
            std::env::temp_dir().join(format!("hookshot-rust-fonts-{}.cpp", std::process::id()));
        let _ = fs::remove_file(&out);
        let bytes = write(&out, &crate::kit::root()).unwrap();
        let text = fs::read_to_string(&out).unwrap();
        assert!(bytes > 0);
        assert!(text.contains("hookshot_font_body_size"));
        let again = fs::metadata(&out).unwrap().modified().unwrap();
        write(&out, &crate::kit::root()).unwrap();
        assert_eq!(again, fs::metadata(&out).unwrap().modified().unwrap());
        let _ = fs::remove_file(out);
    }
}
